private static int getPrefixLength(String path) {
    int prefixLength = org.apache.commons.io.FilenameUtils.getPrefixLength(path);
    if (prefixLength > 0) {
        return prefixLength;
    }
    if (path.length() == 2 && path.charAt(0) >= 'A' && path.charAt(0) <= 'Z' && path.charAt(1) == ':') {
        return 2;
    }
    return 0;
}
